Method.Implementation:
write !, "UserAction: " _ Type _ " " _ Name 

#; Note if you implement this method yourself you can remove all the code below, this is just included
#; for backward compatibility with previous versions of the source control hooks.
#; Get deprecated Flags parameter
Set flags=..%GetParameter("Flags")
Set Action=0,Target="",Msg="",Reload=0
If Type=0 {
	Set menu=$piece(Name,",")
	If menu'="%SourceMenu",menu'="%SourceContext" Quit $$$OK
	Set name=$piece(Name,",",2)
	Set action=$case(name,"%CheckIn":-1,"%CheckOut":0,"%AddToSourceControl":1,"%GetLatest":3,"%UndoCheckout":10,:-2)
	If action=-2 Quit $$$OK
} ElseIf Type=1 {
	Set action=Name
}
#; Do not need source control when deleting an item that is not in source control
If action=2,'..IsInSourceControl(InternalName) Quit $$$OK
#; Default to displaying dialog if no Flags parameter defined as this is what previous source control did
If action<3 {
	If flags="" {
		Set Action=1
	} Else {
		Set Action=+$extract(flags,action+2)
	}
}
write !, "UserAction: new act: " _ Action _ ", " _ Type _ ", " _Name  _ ", " _ InternalName
#; If we do not want the dialog then just call the method here
If Action=0 {
	Quit ..AfterUserAction(Type,Name,InternalName,1,,.Reload)
} Else {
	If action>-2,action<3 {
		Set Target=$$$FormatMessage(,"%Studio",$case(action,-1:"CheckInDialog",0:"CheckOutDialog",1:"AddDialog",2:"RemoveDialog"),,InternalName)
	} Else {
		Quit $$$ERROR($$$StudioSourceActionInvalid,Name,InternalName)
	}
}
Quit $$$OK

write !, "In OnMenuItem: " _ MenuName

Set menu=$piece(MenuName,","),name=$piece(MenuName,",",2)
If menu'="%SourceMenu",menu'="%SourceContext" Quit $$$OK
If InternalName="" Quit $$$OK
Set sc=..GetStatus(InternalName,.isinsourcecontrol,.editable,.ischeckedout)
Set isinsourcecontrol=+$get(isinsourcecontrol),editable=+$get(editable),ischeckedout=+$get(ischeckedout)

If $$$ISERR(sc) Quit sc
If name="%CheckOut" {
	If ischeckedout||('isinsourcecontrol) Set Enabled=0
} ElseIf name="%CheckIn" {
	If 'isinsourcecontrol||('ischeckedout) Set Enabled=0
} ElseIf name="%UndoCheckout" {
	If 'isinsourcecontrol||('ischeckedout) Set Enabled=0
} ElseIf name="%GetLatest" {
	If ischeckedout||('isinsourcecontrol) Set Enabled=0
} ElseIf name="%AddToSourceControl" {
	If isinsourcecontrol||(InternalName="") Set Enabled=0
}
Quit $$$OK

   
	set tStatus = $$$OK
	
	set username = "lpjnaras"
	Set file=..ExternalName(IntName)
    If file="" Quit $$$OK
	write !, "CheckOut file: " _ file
	SET baseDir = "C:\EnsembleSC\" 
	SET fullFile = baseDir _ file
	write !, "CheckOut: " _ fullFile
	 
	If ##class(%File).Exists(fullFile)
	{
				
	  Set cmd= "svn --username " _ username _ " export  " _ fullFile 
	
	  Set status = $ZF(-1, cmd)
	
	  write !, "Svn export " _ cmd _ " : " _ status
	  if status = 0
	  {
			
	    try
	    {
           Set sc=$$Import^%occSAX(file,"fv-d-l")
	       If $$$ISOK(sc) {
		
		       Set IsCheckedOut=1
		       Set UserCheckedOut="lpjnaras"
	    }
		} catch excp {
		   write !, "Error in CheckOut " _ excp.Name _ " " _ excp.AsSystemError() _ " " _ file
		   Set tStatus = ex.AsStatus()
	  }

	 }
        

	  Write !,"CheckOut: Imported '",IntName,"' from file: " _ file
	}
	Quit tStatus

   
	set tStatus = $$$OK
	
	set username = "lpjnaras"
	Set file=..ExternalName(IntName)
    If file="" Quit $$$OK
	write !, "Update file: " _ file
	
	write !, "Update " _ fullFile
	 
	If ##class(%File).Exists(fullFile)
	{
	  Do ##class(%File).Delete(fullFile)			
	  Set cmd= "svn --username " _ username _ " update  " _ fullFile 
	
	  Set status = $ZF(-1, cmd)
	
	  write !, "Svn export " _ cmd _ " : " _ status
	  if status = 0
	  {
			
	    try
	    {
           Set sc=$$Import^%occSAX(file,"fv-d-l")
	       If $$$ISOK(sc) {
		
		       Set IsCheckedOut=0
		       Set UserCheckedOut="lpjnaras"
	    }
		} catch excp {
		   write !, "Error in CheckOut " _ excp.Name _ " " _ excp.AsSystemError() _ " " _ file
		   Set tStatus = ex.AsStatus()
	  }

	 }
        

	  Write !,"CheckOut: Imported '",IntName,"' from file: " _ file
	}
	Quit tStatus

set stat = $$$ERROR(9100, "Cound not add") SET fullPath = "C:\EnsembleSC" SET fileParts = $Length(fName, "/") Write !, fileParts FOR ind=1:1:fileParts { set dirName = $PIECE(fName, "/", ind) set fullPath = fullPath _ "\" _ dirName Set cmd = "svn info " _ fullPath Set stat = $ZF(-1, cmd) Write !, cmd _ " - SVN STAT: " _ stat If stat '= 0 { Set cmd = "svn add " _ fullPath Set stat = $ZF(-1, cmd) Write !, cmd _ " - SVN STAT: " _ stat }
}
Quit stat

Write !, "ExternalName: " _ InternalName
Set name=..Name(InternalName)
// Quit $select(name="":"",1:^Sources_$translate(name,"\","/"))
Write !, "in ExternalName: " , InternalName , " new name: ", name
if name = ""
{
	Quit InternalName
}
else
{
	Quit name
}

If $data(^Sources)'=11 
{
	Set src = ..setSources()
	Write !,"^Sources is not setup so hooks will not work"
	Set src = $data(^Sources) 
	Write !, "Sources set: " _ src
}		
// For an abstract document, use the GetOther() method to try to determine its "real" class
If ##class(%RoutineMgr).UserType(InternalName,.docclass,.doctype) {
	// Check for a real abstract document subclass (or GetOther() may not work)
	If $classmethod(docclass,"%IsA","%Studio.AbstractDocument") {
		// Grab the actual name
		Set actualName = $classmethod(docclass,"GetOther",InternalName)
		// The actualName is only valid if we get a single .cls as a result
		If actualName'[",",$ZCVT($P(actualName,".",$L(actualName,".")),"U")="CLS" {
			// We use what GetOther() gives us, thus Demo.Loan.FindRateProcess.bpl becomes Demo.Loan.FindRateProcess.cls
			Set InternalName = actualName
		}
	}
}	
Write !, "in Name:" , InternalName
If $$CheckProtect^%qccServer(InternalName) Quit ""
Set nam=$p(InternalName,".",1,$l(InternalName,".")-1),ext=$p(InternalName,".",$l(InternalName,".")),ext=$zcvt(ext,"u")
If nam="" Quit ""
If ext="PRJ",nam["Default_" Quit ""
If ext="CLS",$$$defClassKeyGet(nam,$$$cCLASSgeneratedby)'="" Quit ""
Set default=0
Set p=$order(^Sources(ext,nam)) 
For  s p=$order(^Sources(ext,p),-1) Quit:p=""  If $extract(nam,1,$length(p))=p,$data(^Sources(ext,p),found) Quit
If $data(found)=0,$data(^Sources(ext,"*"),found) Set default=1
If $data(found)=0 Quit ""
If InternalName["/" {
	Set InternalName=$extract(InternalName,$length(p)+1,*)
	Set newName = $translate(found_$translate(InternalName,"%","_"),"\","/")
	Write !, InternalName , " new name: ", newName
    Quit newName
}
If ext="CLS"||(ext="PRJ")||(##class(%RoutineMgr).UserType(InternalName)) 
{
   Set newName = $translate(found_$translate(nam,".%","/")_".xml","\","/")
   Write !, InternalName , " new name: ", newName
   Quit newName
}
Set newName = $translate($g(found)_$tr(nam,"%"_$s(default:".",1:""),"_/")_".xml","\","/")
Write !, InternalName , " new name: ", newName
Quit newName

kill ^Sources
set ^Sources="C:\EnsembleSC"
set ^Sources("CLS","*")="cls/"
set sc=$$$OK
/****
&sql(declare SU1 cursor for
	select ID into :class 
	from %Dictionary.ClassDefinition where NOT (ID %STARTSWITH '%'))
&sql(open SU1)
for {
	&sql(fetch SU1)
	quit:SQLCODE
	set sc= Name(class_".CLS")
	Write !, class
	quit:'sc
}
****/
quit sc
