Set Editable=1,IsCheckedOut=0,UserCheckedOut="",IsInSourceControl=0
try
{
	write !, "Check status: " _ InternalName 
    Set file = ""
    Set file=..ExternalName(InternalName)

    SET baseDir = "C:\EnsembleSC\" 
    SET fullFile = baseDir _ file

	if ( ##class(%File).Exists(fullFile) )
	{
       Write !, "GetStatus from SVN: " _ fullFile

       Set cmd = "svn status " _ fullFile _ "> c:\Temp\svnStat.txt"
       Set stat = $ZF(-1, cmd)
       Write !, cmd _ " - SVN STAT: " _ stat
	
       if stat = 0
       {	
          Set stat = ..ReadSvnFile(.IsCheckedOut,.UserCheckedOut,.IsInSourceControl)
       }
	}
   
} catch {
	write !, "Error in GetStatus"
}

write !, "IsInSourceControl: " _ IsInSourceControl
write !, "IsCheckedOut: " _ IsCheckedOut

Quit $$$OK
